#include <zephyr/ztest.h>

/**
 * @brief A simple test case that always passes.
 */
static void test_simple_pass(void)
{
	zassert_true(1, "Assertion should pass");
}

/**
 * @brief A simple test case that always fails.
 */
static void test_simple_fail(void)
{
	zassert_false(1, "Assertion should fail");
}

/* Define the test suite. The compilation error suggests the semicolon
 * at the end of this macro was missing.
 */
ztest_test_suite(my_app_tests,
		 ztest_unit_test(test_simple_pass),
		 ztest_unit_test(test_simple_fail)
		 );

/**
 * @brief Main entry point for the test suite.
 */
void test_main(void)
{
	ztest_run_test_suite(my_app_tests);
}
